// scripts/build-route-catalogue.mjs
//
// The list of page routes the analytics beacon is allowed to name.
//
//   npm run build:route-catalogue
//
// ══ Why a generated file and not a runtime directory walk ═════════════════
//
// POST /api/track refuses any path that is not one of the product's own page
// routes — the allow-list is what stops a stranger filling AnalyticsEvent
// with arbitrary strings, and it is also how a raw URL becomes a route
// PATTERN ("/app/quotes/[id]", never the id). The natural source of that
// list is the app/ tree, but a Vercel function cannot read app/ at runtime:
// the source is not in the bundle. So the tree is walked here, at build
// time, and written to a module both the browser and the route import.
//
// scripts/check-product-analytics.mjs regenerates the list in memory and
// fails when the committed module disagrees, so a page added without a
// rebuild fails the check rather than silently going untracked.
//
// Route groups — "(marketing)" — are stripped the way Next strips them;
// dynamic segments keep their bracketed spelling because that IS the
// pattern. No parallel or intercepting routes exist in this tree; the walk
// would need teaching if one arrived (an "@" or "(.)" segment fails below).

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const OUT = path.join(ROOT, "lib", "analytics", "product", "routeCatalogue.generated.js");

/** Every page route pattern under app/, sorted. Pure over the file system. */
export function collectRoutes(appDir = path.join(ROOT, "app")) {
  const out = [];
  const walk = (dir, segments) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (entry.isDirectory()) {
        if (entry.name === "api") continue;
        if (entry.name.startsWith("@") || entry.name.startsWith("(.")) {
          throw new Error(`build-route-catalogue: unsupported segment "${entry.name}" under ${dir}`);
        }
        // A route group contributes nothing to the URL.
        const next = /^\(.+\)$/.test(entry.name) ? segments : [...segments, entry.name];
        walk(path.join(dir, entry.name), next);
      } else if (entry.name === "page.js") {
        out.push("/" + segments.join("/"));
      }
    }
  };
  walk(appDir, []);
  return [...new Set(out)].sort();
}

export function renderModule(routes) {
  return [
    "// lib/analytics/product/routeCatalogue.generated.js",
    "//",
    "// GENERATED by scripts/build-route-catalogue.mjs — do not edit by hand.",
    "// Every page route in app/, as the pattern Next matches it by. This is the",
    "// allow-list POST /api/track holds a path against and the table the",
    "// browser normalises a URL with before anything leaves it. Regenerate with",
    "// `npm run build:route-catalogue`; check:product-analytics fails when the",
    "// tree and this file disagree.",
    "",
    "export const ROUTE_PATTERNS = Object.freeze([",
    ...routes.map((r) => `  ${JSON.stringify(r)},`),
    "]);",
    "",
  ].join("\n");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const routes = collectRoutes();
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, renderModule(routes));
  console.log(`route catalogue: ${routes.length} patterns → ${path.relative(ROOT, OUT)}`);
}
